/** The yyyy-mm-dd `days` days after `date`. */
function addDays(date: string, days: number): string {
  return new Date(Date.parse(`${date}T00:00:00Z`) + days * 86_400_000).toISOString().slice(0, 10);
}

/** The late charge on an overdue claim's `figure`, in cents: for every full 30 days it is overdue,
 *  the late percent in force on that boundary date (the due-by plus 30, 60, 90 ... days) of it, each
 *  rounded by the claim's rounding (`halfUp`), added up; a boundary at 0.00 adds nothing. Nothing
 *  while it is not overdue. Never bound by a statement: it follows the sheet's today. */
export function lateChargeCents(claim: Claim, figure: bigint, late: Late): bigint {
  if (!overdue(claim, late.today) || isCorrection(claim)) return 0n;
  const periods = Math.floor(daysBetween(claim.dueBy, late.today) / 30);
  let total = 0n;
  for (let k = 1; k <= periods; k++) {
    const pct = hundredths(late.pctOn(addDays(claim.dueBy, 30 * k)));
    if (pct === 0n) continue;
    // cents * hundredths-of-a-percent is in ten-thousandths of a cent.
    total += roundTenThousandths(figure * pct, claim.halfUp);
  }
  return total;
}


/** A person's due-total, in cents: the sum of their counted claims' figures, each already rounded —
 *  a settled claim's fixed due, else the figure a statement bound it to, else live at `pctOn(claim's date)`, plus any late charge and at least `floor`, the rate in force on the claim's
 *  date (at `pct`, the rate in force on the sheet's today, when no `pctOn` is given). 0 with
 *  nothing that counts. With `late`, an overdue claim's late charge is added on top. Null (n/a) when there is no rate today, unless some settled claim keeps a
 *  figure: then it is the sum of the figures there are. With `cap`, it is at most the cap (an n/a one
 *  is not capped). */
export function personDueCents(claims: Claim[], floor: FloorOn, pct: string | undefined, pctOn?: (date: string) => string | undefined, late?: Late, cap?: string | null): bigint | null {
  let sum = 0n;
  let any = false;
  for (const c of counted(claims)) {
    const due = claimDueCents(c, floor, pctOn ? pctOn(c.date) : pct, late);
    if (due === null) continue;
    sum += due;
    any = true;
  }
  if (pct === undefined && !any) return null;
  return capCents(sum, cap);
}

/** A due-total at most the sheet's `cap` (null or blank: no cap); n/a is not capped. */
export function capCents(due: bigint | null, cap?: string | null): bigint | null {
  if (due === null || cap == null || cap === '') return due;
  const most = hundredths(cap);
  return due > most ? most : due;
}

/** How much a due-total is over the sheet's `cap`: 0 when it is not (or is n/a, or there is no cap). */
export function excessCents(due: bigint | null, cap?: string | null): bigint {
  const capped = capCents(due, cap);
  return due === null || capped === null ? 0n : due - capped;
}

/** Whether a claim is overdue: it is OPEN (or PENDING), not deferred, and its due-by is before the sheet's `today`. */
export function overdue(claim: Claim, today: string): boolean {
  return isOpen(claim) && !claim.deferred && today !== '' && claim.dueBy < today;
}

/** These claims' overdue ones: their count, and their dues with late charges added up in cents (n/a ones skipped).
 *  `pctOn` is the rate in force on a claim's date. */
export function overdueFigures(claims: Claim[], late: Late, floor: FloorOn, pctOn: (date: string) => string | undefined): { count: number; cents: bigint } {
  const over = claims.filter((c) => overdue(c, late.today));
  const cents = over.reduce<bigint>((sum, c) => sum + (claimDueCents(c, floor, pctOn(c.date), late) ?? 0n), 0n);
  return { count: over.length, cents };
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asOfKey, asOfPath, useAsOf } from '../asof/useAsOf';

/** A grade's rate as the server sends it: `pct` is a percent with two decimals, `from` the date it
 *  is in force from (yyyy-mm-dd), or null when it applies from the beginning of time; `to` the
 *  date it applies through, or null when it has no end. */
export type Rate = { grade: string; pct: string; from: string | null; to: string | null };

export const ratesKey = (sheet: string) => ['sheet', sheet, 'rates'] as const;

/** The sheet's rates, by grade then from-date (the one with none first), re-read whenever the sheet is loaded. */
export function useRates(sheet: string) {
  const [asOf] = useAsOf();
  return useQuery({
    queryKey: asOfKey(ratesKey(sheet), asOf),
    queryFn: () => getJson<Rate[]>(asOfPath(`/api/sheets/${encodeURIComponent(sheet)}/rates`, asOf)),
    staleTime: 0,
    gcTime: 0,
  });
}

/** A percent the server accepts: 0.00 or more, with up to two decimals. */
export const PCT = /^\d{1,5}(\.\d{1,2})?$/;

/**
 * The grade's rate in force on `date` (yyyy-mm-dd): the one whose from-date is the latest on or
 * before it, a rate with no from-date applying from the beginning of time. Undefined when none does, or when that one's to-date is before `date`.
 */
export function rateOn(rates: Rate[], grade: string, date: string): string | undefined {
  let found: Rate | undefined;
  for (const r of rates) {
    if (r.grade !== grade || (r.from !== null && r.from > date)) continue;
    if (found === undefined || (found.from ?? '') < (r.from ?? '')) found = r;
  }
  return found !== undefined && (found.to === null || found.to >= date) ? found.pct : undefined;
}

/** "12.34" as a whole number of hundredths (1234n), exactly. */
export function hundredths(value: string): bigint {
  const negative = value.startsWith('-');
  const [whole, frac = ''] = (negative ? value.slice(1) : value).split('.');
  const cents = BigInt(whole) * 100n + BigInt((frac + '00').slice(0, 2));
  return negative ? -cents : cents;
}

function format(cents: bigint): string {
  const abs = cents < 0n ? -cents : cents;
  return `${cents < 0n ? '-' : ''}${abs / 100n}.${(abs % 100n).toString().padStart(2, '0')}`;
}

/**
 * What is due on `amount` (two decimals) at `pct` percent: amount times pct divided by 100,
 * rounded to two decimals (half up with `halfUp`, else half to even), worked in whole numbers so it
 * is exact. In cents, or null when there is no rate.
 */
export function dueCents(amount: string, pct: string | undefined, halfUp = false): bigint | null {
  if (pct === undefined) return null;
  // cents * hundredths-of-a-percent is in ten-thousandths of a cent.
  // Rounded on its size, so a negative amount (a correction) rounds like a positive one.
  const product = hundredths(amount) * hundredths(pct);
  const abs = product < 0n ? -product : product;
  const rounded = roundTenThousandths(abs, halfUp);
  return product < 0n ? -rounded : rounded;
}

/** A size in ten-thousandths of a cent, rounded to whole cents: half up with `halfUp`, else half to even. */
export function roundTenThousandths(abs: bigint, halfUp: boolean): bigint {
  const whole = abs / 10000n;
  const rest = abs % 10000n;
  return rest > 5000n || (rest === 5000n && (halfUp || whole % 2n === 1n)) ? whole + 1n : whole;
}

/** A due in cents as shown: two decimals, or n/a when there is no rate. */
export function showDue(cents: bigint | null): string {
  return cents === null ? 'n/a' : format(cents);
}

/** Dues added up, skipping the n/a ones. */
export function totalDue(dues: Array<bigint | null>): string {
  return format(dues.reduce<bigint>((sum, d) => (d === null ? sum : sum + d), 0n));
}

/** The figures (n/a skipped) added up, leaving out the single highest and lowest when three or more. */
export function trimmedTotal(dues: Array<bigint | null>): string {
  const figures = dues.filter((d): d is bigint => d !== null).sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
  return totalDue(figures.length >= 3 ? figures.slice(1, -1) : figures);
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HttpError, postJson, putJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { PersonCells, PersonColumns } from '../../slots/defs/personRow';
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { QuickAddBar } from './QuickAddBar';
import { ShowRetired, useShowRetired } from './ShowRetired';
import { useSheetToday } from '../sheet/useSheet';
import { GRADES, gradeOn, peopleKey, usePeople, type Person } from './usePeople';

/** The sheet's people: one form to add a person or edit the one whose editor is open, and the list. */
function PeoplePanel({ user, sheet }: { user: string; sheet: string }) {
  const queryClient = useQueryClient();
  const { data: everyone = [] } = usePeople(sheet);
  // Retired people have no row unless they are shown; their claims still count in every total.
  const [showRetired] = useShowRetired();
  const people = showRetired ? everyone : everyone.filter((p) => !p.retired);
  const [editing, setEditing] = useState<number | null>(null);
  // The version of the person the editor loaded: a save is refused if someone saved since.
  const [version, setVersion] = useState(0);
  const [name, setName] = useState('');
  const [grade, setGrade] = useState<string>('A');
  // The date the form's grade is in force from; blank for the sheet's today.
  const [gradeFrom, setGradeFrom] = useState('');
  // The person's own terms in days; blank for none.
  const [terms, setTerms] = useState('');
  const today = useSheetToday(sheet);
  const [blank, setBlank] = useState(false);
  const base = `/api/sheets/${encodeURIComponent(sheet)}/people`;

  const submitOnce = useSubmitOnce();
  const save = useMutation({
    mutationFn: (p: { id: number | null; name: string; grade: string; gradeFrom: string; terms: string; version: number }) =>
      p.id === null
        ? postJson<Person>(base, { name: p.name, grade: p.grade, gradeFrom: p.gradeFrom, terms: p.terms, user })
        : putJson<Person>(`${base}/${p.id}`, { name: p.name, grade: p.grade, gradeFrom: p.gradeFrom, terms: p.terms, version: p.version, user }),
    onError: async (e) => {
      // Someone else saved this person since the editor loaded it: the form shows what is stored
      // now (and that version), and the list is re-read so a fresh editor loads it too.
      if (e instanceof HttpError && e.status === 409 && e.body) {
        const current = JSON.parse(e.body) as Person;
        setName(current.name);
        setGrade(gradeOn(current, today));
        setTerms(current.terms === null ? '' : String(current.terms));
        setVersion(current.version);
        await queryClient.invalidateQueries({ queryKey: peopleKey(sheet) });
        return;
      }
      // Any other refusal (an invalid value) keeps its error showing but closes the editor, so the
      // form is back to adding and nothing typed for the refused save carries into the next one.
      setEditing(null);
      setName('');
      setGrade('A');
      setGradeFrom('');
      setTerms('');
    },
    onSuccess: async () => {
      setEditing(null);
      setName('');
      setGrade('A');
      setGradeFrom('');
      setTerms('');
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheet) });
    },
  });

  // An error goes as soon as its form is changed or submitted again, or an editor is opened.
  const clearError = () => {
    save.reset();
    setBlank(false);
  };

  const open = (p: Person) => {
    clearError();
    setEditing(p.id);
    setVersion(p.version);
    setName(p.name);
    setGrade(gradeOn(p, today));
    setGradeFrom('');
    setTerms(p.terms === null ? '' : String(p.terms));
  };
  const cancel = () => {
    clearError();
    setEditing(null);
    setName('');
    setGrade('A');
    setGradeFrom('');
    setTerms('');
  };

  return (
    <section data-testid="people-panel">
      <h2>People</h2>
      <form
        data-testid="person-form"
        onSubmit={(e) => {
          e.preventDefault();
          if (name.trim() === '') {
            // Refused here, before anything is sent: the store and the audit file are untouched.
            save.reset();
            setBlank(true);
            return;
          }
          setBlank(false);
          submitOnce(() => save.mutateAsync({ id: editing, name, grade, gradeFrom: gradeFrom.trim(), terms: terms.trim(), version }));
        }}
      >
        <label>
          Name{' '}
          <input
            data-testid="person-form-name"
            value={name}
            onChange={(e) => {
              setName(e.target.value);
              clearError();
            }}
          />
        </label>{' '}
        <label>
          Grade{' '}
          <select
            data-testid="person-form-grade"
            value={grade}
            onChange={(e) => {
              setGrade(e.target.value);
              clearError();
            }}
          >
            {GRADES.map((g) => (
              <option key={g} value={g}>
                {g}
              </option>
            ))}
          </select>
        </label>{' '}
        <label>
          From{' '}
          <input
            data-testid="person-form-grade-from"
            placeholder={today || 'yyyy-mm-dd'}
            value={gradeFrom}
            onChange={(e) => {
              setGradeFrom(e.target.value);
              clearError();
            }}
          />
        </label>{' '}
        <label>
          Terms{' '}
          <input
            data-testid="person-form-terms"
            placeholder="days"
            size={5}
            value={terms}
            onChange={(e) => {
              setTerms(e.target.value);
              clearError();
            }}
          />
        </label>{' '}
        <button type="submit" data-testid="person-form-submit" disabled={save.isPending}>
          {editing === null ? 'Add' : 'Save'}
        </button>
        {editing !== null && (
          <>
            {' '}
            <button type="button" data-testid="person-form-cancel" onClick={cancel}>
              Cancel
            </button>
          </>
        )}
        {(blank || save.isError) && (
          <span data-testid="person-form-error" role="alert">
            {' '}
            {blank
              ? 'A name is required.'
              : save.error instanceof HttpError && save.error.status === 409
                ? 'Someone else saved this person since you opened it; the form now shows what is stored.'
                : 'Could not save this person.'}
          </span>
        )}
      </form>
      <QuickAddBar user={user} sheet={sheet} />
      <ShowRetired />
      <table data-testid="people-list">
        <thead>
          <tr>
            <th>Name</th>
            <th>Grade</th>
            <th>Terms</th>
            <th />
            <PersonColumns.Slot user={user} sheet={sheet} />
          </tr>
        </thead>
        <tbody>
          {people.map((p) => (
            <tr key={p.id} data-testid={`person-row-${p.id}`}>
              <td data-testid="person-name">{p.name}</td>
              <td data-testid="person-grade">{gradeOn(p, today)}</td>
              <td data-testid="person-terms">{p.terms ?? ''}</td>
              <td>
                <button type="button" data-testid={`person-edit-${p.id}`} onClick={() => open(p)}>
                  Edit
                </button>
              </td>
              <PersonCells.Slot user={user} sheet={sheet} person={p} />
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

export const contribution = SheetPanels.fill({ order: 10, Component: PeoplePanel });

